     {  $\left(2 - 3 x\right) \left(x - 3\right) $ }
    { $\left(x + 3\right) \left(3 x + 2\right) $  }
\loigiai{
$2.(x + 3)+- 3 x \left(x + 3\right) = \left(2 - 3 x\right) \left(x + 3\right) $
}\end{ex}

